import React, { useState } from 'react';
import { Link } from 'react-router-dom'; // මේක අනිවාර්යයි
import { 
  UserIcon, MapPinIcon, PhoneIcon, TruckIcon, 
  ClockIcon, GiftIcon, CheckCircleIcon, 
  HomeIcon, ShoppingBagIcon 
} from '@heroicons/react/24/outline';

const Orders = () => {
  const [order, setOrder] = useState({
    orderID: "ORD-2026-991",
    status: "Pending",
    items: [
      { name: "Keells Sugar 1kg", quantity: 2, isPacked: false },
      { name: "Anchor Milk Powder 400g", quantity: 1, isPacked: false },
      { name: "Munchee Super Cream Cracker", quantity: 3, isPacked: false }
    ],
    customer: {
      name: "Saman Kumara",
      phoneNumber: "071-2345678",
      address: { houseNumber: "No. 45/A", street: "Temple Road", landMark: "Near Clock Tower" }
    }
  });

  const statuses = ['Pending', 'Packing', 'Out for Delivery', 'Delivered'];
  const currentIdx = statuses.indexOf(order.status);

  const advanceStatus = () => {
    if (currentIdx < statuses.length - 1) {
      setOrder({ ...order, status: statuses[currentIdx + 1] });
    }
  };

  const togglePacked = (idx) => {
    const newItems = [...order.items];
    newItems[idx].isPacked = !newItems[idx].isPacked;
    setOrder({ ...order, items: newItems });
  };

  return (
    <div className="flex min-h-screen bg-gray-100 font-sans text-gray-900">
      
      {/* SIDEBAR */}
      <aside className="w-64 bg-gradient-to-b from-blue-800 to-blue-950 text-white flex flex-col shadow-xl">
        <div className="p-6 border-b border-blue-700">
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <HomeIcon className="w-8 h-8 text-yellow-400" /> BigMart
          </h1>
        </div>
        <nav className="mt-6 flex-1">
          {/* Active Orders Link */}
          <Link to="/orders" className="flex items-center gap-3 px-6 py-4 bg-blue-700 border-r-4 border-yellow-400">
            <TruckIcon className="w-5 h-5 text-yellow-400" />
            <span className="font-bold">Active Orders</span>
          </Link>
          {/* History Link */}
          <Link to="/history" className="flex items-center gap-3 px-6 py-4 hover:bg-blue-800 transition-colors">
            <ShoppingBagIcon className="w-5 h-5 text-blue-300" />
            <span>Order History</span>
          </Link>
        </nav>
      </aside>

      {/* MAIN CONTENT */}
      <div className="flex-1 flex flex-col">
        <header className="bg-white shadow-sm p-8 flex justify-between items-center">
          <h2 className="text-3xl font-bold text-gray-800 tracking-tight">Orders Management</h2>
          <span className="bg-blue-100 text-blue-700 px-4 py-1 rounded-full text-xs font-black uppercase">{order.status}</span>
        </header>
        <main className="p-8">
           {/* ... (ඔයාගේ ඉතිරි Order Card code එක මෙතනට එනවා) ... */}
           <div className="bg-white rounded-xl shadow-md p-8 border border-gray-200">
              <h3 className="text-xl font-bold text-blue-900 mb-6">{order.orderID} - {order.customer.name}</h3>
              {/* Stepper & Details - පරණ විදිහටම තියන්න */}
              <button onClick={advanceStatus} className="mt-10 w-full bg-blue-700 text-white py-4 rounded-xl font-bold">
                ADVANCE TO {statuses[currentIdx+1]?.toUpperCase()}
              </button>
           </div>
        </main>
      </div>
    </div>
  );
};

export default Orders;
